use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse};
use serde::{Deserialize, Serialize};
use reqwest::Client;
use std::net::IpAddr;
use std::time::Duration;

#[derive(Deserialize)]
struct WebhookConfig {
    callback_url: String,
    event_type: String,
}

#[derive(Serialize)]
struct MetadataResponse {
    instance_id: String,
    role_arn: String,
    credentials: Option<String>,
}

async fn register_webhook(req: HttpRequest, config: web::Json<WebhookConfig>) -> HttpResponse {
    // Validate URL scheme
    let url = match url::Url::parse(&config.callback_url) {
        Ok(u) => u,
        Err(_) => return HttpResponse::BadRequest().body("Invalid URL"),
    };

    if url.scheme() != "http" && url.scheme() != "https" {
        return HttpResponse::BadRequest().body("Only HTTP(S) allowed");
    }

    // DNS resolution check - resolve hostname and verify it's not internal
    let host = match url.host_str() {
        Some(h) => h.to_string(),
        None => return HttpResponse::BadRequest().body("No host in URL"),
    };

    // First resolution - check if IP is public
    let addrs: Vec<IpAddr> = match tokio::net::lookup_host(format!("{}:80", host)).await {
        Ok(a) => a.map(|s| s.ip()).collect(),
        Err(_) => return HttpResponse::BadRequest().body("DNS resolution failed"),
    };

    for addr in &addrs {
        if is_internal_ip(addr) {
            return HttpResponse::Forbidden().body("Internal IPs not allowed");
        }
    }

    // Time-of-check-to-time-of-use gap: DNS can rebind between check and use
    // The actual HTTP request happens after validation
    tokio::time::sleep(Duration::from_millis(50)).await;

    let client = Client::builder()
        .timeout(Duration::from_secs(5))
        .build()
        .unwrap();

    // Send verification ping to webhook URL - TOCTOU: DNS may now resolve differently
    let response = match client.get(&config.callback_url).send().await {
        Ok(r) => r,
        Err(e) => return HttpResponse::BadGateway().body(format!("Callback failed: {}", e)),
    };

    let body = response.text().await.unwrap_or_default();

    HttpResponse::Ok().json(serde_json::json!({
        "status": "registered",
        "event_type": config.event_type,
        "verification_response_length": body.len()
    }))
}

async fn fetch_internal_resource(req: HttpRequest, path: web::Path<String>) -> HttpResponse {
    // Internal endpoint that fetches from instance metadata or internal services
    let resource_path = path.into_inner();
    let client = Client::new();

    let internal_url = format!("http://169.254.169.254/latest/meta-data/{}", resource_path);

    match client.get(&internal_url).send().await {
        Ok(resp) => {
            let body = resp.text().await.unwrap_or_default();
            HttpResponse::Ok().body(body)
        }
        Err(_) => HttpResponse::InternalServerError().body("Failed to fetch metadata"),
    }
}

fn is_internal_ip(ip: &IpAddr) -> bool {
    match ip {
        IpAddr::V4(v4) => {
            v4.is_private() || v4.is_loopback() || v4.is_link_local()
            // Note: 169.254.169.254 is link-local, caught by is_link_local()
        }
        IpAddr::V6(v6) => {
            v6.is_loopback()
        }
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/api/webhooks/register", web::post().to(register_webhook))
            .route("/internal/metadata/{path:.*}", web::get().to(fetch_internal_resource))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
